import React, { useEffect, useState } from 'react';
import { Link, NavLink, useNavigate } from 'react-router-dom'



function Header({ title }) {

    const [loading, setLoading] = useState(true);

    useEffect(() => {
        // Hide loader after 1.5 seconds
        const timer = setTimeout(() => {
            setLoading(false);
        }, 2000);

        return () => clearTimeout(timer);
    }, []);

    const redirect = useNavigate();
    const user_logout = () => {
        sessionStorage.removeItem('u_id')
        sessionStorage.removeItem('u_name')

        alert('Logout Success!')
        redirect('/');
        return false;

    }

    return (
        <div>
            {/* Spinner Start */}

            {loading && (
                <div
                    id="spinner"
                    style={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        width: '100vw',
                        height: '100vh',
                        backgroundColor: '#ffffff',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        zIndex: 2147483647
                    }}
                >
                    <div
                        style={{
                            width: '48px',
                            height: '48px',
                            border: '5px solid #dee2e6',
                            borderTop: '5px solid #06BBCC',
                            borderRadius: '50%',
                            animation: 'loader-spin 0.8s linear infinite'
                        }}
                    />
                    <style>
                        {`
                @keyframes loader-spin {
                    from { transform: rotate(0deg); }
                    to { transform: rotate(360deg); }
                }
            `}
                    </style>
                </div>
            )}

            {/* Spinner End */}
            {/* Navbar Start */}
            <nav className="navbar navbar-expand-lg bg-white navbar-light shadow sticky-top p-0">
                <a href="index.html" className="navbar-brand d-flex align-items-center px-4 px-lg-5">
                    <h2 className="m-0 text-primary"><i className="fa fa-book me-3" />eLEARNING</h2>
                </a>
                <button type="button" className="navbar-toggler me-4" data-bs-toggle="collapse" data-bs-target="#navbarCollapse">
                    <span className="navbar-toggler-icon" />
                </button>
                <div className="collapse navbar-collapse" id="navbarCollapse">
                    <div className="navbar-nav ms-auto p-4 p-lg-0">
                        <NavLink to="/" className="nav-item nav-link">Home</NavLink>
                        <NavLink to="/about" className="nav-item nav-link">About</NavLink>
                        <NavLink to="/courses" className="nav-item nav-link">Courses</NavLink>
                        <NavLink to="/team" className="nav-item nav-link">Our Team</NavLink>
                        <NavLink to="/testimonial" className="nav-item nav-link">Testimonial</NavLink>
                        <NavLink to="/contact" className="nav-item nav-link">Contact</NavLink>

                        {
                            (() => {
                                if (sessionStorage.getItem('u_id')) {
                                    return (
                                        <div className="nav-item dropdown">
                                            <a href="#" className="nav-link dropdown-toggle" data-bs-toggle="dropdown">Hi.. {sessionStorage.getItem('u_name')}</a>
                                            <div className="dropdown-menu fade-down m-0">
                                                <NavLink to="/prof" className="dropdown-item">Profile</NavLink>
                                            </div>
                                        </div>
                                    )
                                }
                            }
                            )()}



                    </div>

                    {
                        (() => {
                            if (sessionStorage.getItem('u_id')) {
                                return (
                                    <Link to="#" onClick={user_logout} className="btn btn-primary py-4 px-lg-5 d-none d-lg-block">Logout<i className="fa fa-arrow-right ms-3" /></Link>
                                )
                            }
                            else {
                                return (
                                    <Link to="/login" className="btn btn-primary py-4 px-lg-5 d-none d-lg-block">Login<i className="fa fa-arrow-right ms-3" /></Link>
                                )
                            }
                        }
                        )()}


                </div>
            </nav>
            {/* Navbar End */}
            {/* Header Start */}
            <div className="container-fluid bg-primary py-5 mb-5 page-header">
                <div className="container py-5">
                    <div className="row justify-content-center">
                        <div className="col-lg-10 text-center">
                            <h1 className="display-3 text-white animated slideInDown">{title}</h1>
                            <nav aria-label="breadcrumb">
                                <ol className="breadcrumb justify-content-center">
                                    <li className="breadcrumb-item"><a className="text-white" href="#">Home</a></li>
                                    <li className="breadcrumb-item"><a className="text-white" href="#">Pages</a></li>
                                    <li className="breadcrumb-item text-white active" aria-current="page">About</li>
                                </ol>
                            </nav>
                        </div>
                    </div>
                </div>
            </div>
            {/* Header End */}

        </div>

    )
}

export default Header
